document.querySelectorAll('form[data-print-form]').forEach((form)=>{form.addEventListener('submit',()=>{const next=form.dataset.thanks;if(next){let redirect=form.querySelector('input[name="_next"]');if(!redirect){redirect=document.createElement('input');redirect.type='hidden';redirect.name='_next';form.appendChild(redirect)}redirect.value=new URL(next,window.location.href).href}})});document.querySelectorAll('.menu-toggle').forEach((button)=>{button.addEventListener('click',()=>{const panel=document.getElementById(button.getAttribute('aria-controls'));const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));panel?.classList.toggle('is-open',!open)})});document.querySelectorAll('a[href]').forEach((link)=>{const href=link.getAttribute('href')||'';const match=href.match(/(?:^|\/)(privacy-policy|refund-policy|billing-policy)(?:\.html)?\/?$/);if(match){const locale=document.documentElement.lang.split('-')[0];link.href=`/${locale}/${match[1]}`}});